        _local_git = obj.get(constants.Y_LOCALGIT)
        _image = obj.get(constants.Y_IMAGE)
        _image_credential = obj.get(constants.Y_IMAGE_CREDENTIAL)
        _resources = ResourceRequirements.from_input(obj.get(constants.Y_RESOURCES))
