class Kubernetes:
    def __init__(
        self,
        imports: list[KubernetesImports] | None = None,
        exports: list[KubernetesExports] | None = None,
        mode: str | None = "None",
    ):
        """Initializes the instance.

        Args:
            imports: List of GVKs to import from kubernetes.  By default, any CR used by a script will already have its spec imported.
            exports: List of GVKs to export to kubernetes.  By default, any CR created by a script will not be exported to kubernetes
                unless listed in the exports list. When mode is None, an entry in this list also unblocks import for that GVK.
            mode: Sets the default mode for interacting with resources in Kubernetes.
                This controls the set of resources that CE will publish to Kubernetes, and the set of resources that CE will treat as inputs.
                This setting can be overridden on a per-resource basis using the imports and exports lists, or by an application within their Manifest.
        """
        self.mode = mode
        self.imports = imports
        self.exports = exports

    def to_input(self):
        _rval = {}
        if self.mode is not None:
            _rval[constants.Y_MODE] = self.mode
        if self.imports is not None:
            _rval[constants.Y_IMPORTS] = [x.to_input() for x in self.imports]
        if self.exports is not None:
            _rval[constants.Y_EXPORTS] = [x.to_input() for x in self.exports]
        return _rval

    @staticmethod
    def from_input(obj) -> "Kubernetes | None":
        if not obj:
            return None
        _mode = obj.get(constants.Y_MODE, "None")
        _imports = []
        if obj.get(constants.Y_IMPORTS) is not None:
            for _e in obj.get(constants.Y_IMPORTS):
                _imports.append(KubernetesImports.from_input(_e))
        _exports = []
        if obj.get(constants.Y_EXPORTS) is not None:
            for _e in obj.get(constants.Y_EXPORTS):
                _exports.append(KubernetesExports.from_input(_e))
        return Kubernetes(
            mode=_mode,
            imports=_imports,
            exports=_exports,
        )


